package android.view;
public class MotionEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,ACTION_MOVE=2,ACTION_CANCEL=3,ACTION_HOVER_MOVE=7,ACTION_HOVER_ENTER=9,ACTION_HOVER_EXIT=10,ACTION_POINTER_DOWN=5,ACTION_POINTER_UP=6,AXIS_Z=11,AXIS_RX=12,AXIS_X=0,AXIS_Y=1,AXIS_HAT_X=15,AXIS_HAT_Y=16,AXIS_LTRIGGER=17,AXIS_RTRIGGER=18,AXIS_BRAKE=23,AXIS_GAS=22;final int action,source;final float x,y;public final float[] axes=new float[32];public MotionEvent(int a,float x,float y){this(a,x,y,InputDevice.SOURCE_JOYSTICK);}public MotionEvent(int a,float x,float y,int s){action=a;this.x=x;this.y=y;source=s;}public int getActionMasked(){return action;}public int getActionIndex(){return 0;}public int getPointerId(int i){return 0;}public int getPointerCount(){return 1;}public float getX(){return x;}public float getY(){return y;}public float getX(int i){return x;}public float getY(int i){return y;}public float getAxisValue(int a){return axes[a];}public InputDevice getDevice(){return new InputDevice();}public int getSource(){return source;}}
